/**
 * A course as it exists TODAY. `id` is a stable internal identifier that
 * never changes, even if the campus renames or renumbers the course.
 * `subject` + `number` is the course's CURRENT public identity (e.g.
 * "COMPSCI" + "61A") — the thing a student would type into a search box.
 */
export interface Course {
  id: string;
  subject: string;
  number: string;
  title: string;
}

/**
 * One row per subject+number identity a course has ever held, including its
 * current one. If a course has never been renamed, it has exactly one row
 * here. If it's been renamed twice, it has three rows (two past identities +
 * the current one).
 *
 * `validFrom` / `validUntil` are informational (the term range the identity
 * was in effect; `validUntil: null` means "current"). You are not required
 * to use them to pass the base test suite — see impl/README.md for when
 * they'd matter.
 */
export interface CourseIdentity {
  courseId: string;
  subject: string;
  number: string;
  validFrom: string;
  validUntil: string | null;
}

/**
 * A single term's grade distribution, filed under whatever subject+number
 * was correct AT THE TIME the grades were recorded. This is raw historical
 * data — it is never rewritten after the fact when a course is renamed.
 */
export interface GradeRecord {
  subject: string;
  number: string;
  term: string;
  enrolled: number;
  grades: {
    A: number;
    B: number;
    C: number;
    D: number;
    F: number;
    P: number;
    NP: number;
  };
}
